// Broth-space helper: bx,by in -1..1 across the broth ellipse.
let BRX = 0, BRY = 0, BCY = 0;
const bx = v => CX + v * BRX, by = v => BCY + v * BRY;

function drawSteam(t, dt, front) {
  ctx.save(); ctx.globalCompositeOperation = "screen";
  for (const p of steam) {
    if ((p.phase > Math.PI) !== front) continue;
    const k = p.age / p.life; if (k > 1) continue;
    const rise = k * 300 * S;
    const bend = (Math.sin(p.age * p.sway + p.phase) * (12 + k * 42) + mouse.wind * k * k * 190) * S;
    const x = bx(p.x) + bend + Math.sin(p.age * .6 + p.phase * 2) * 8 * S * k;
    const y = by(p.y) - 12 * S - rise;
    const r = p.r * S * (0.55 + k * 1.9);
    const alpha = Math.sin(Math.min(k, 1) * Math.PI) * .16;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(255,240,220,${alpha})`);
    g.addColorStop(.55, `rgba(230,210,190,${alpha * .45})`);
    g.addColorStop(1, "rgba(220,200,180,0)");
    ctx.fillStyle = g;
    ctx.save(); ctx.translate(x, y); ctx.rotate(p.spin * p.age * .3); ctx.scale(1, 1.35);
    circle(0, 0, r); ctx.fill(); ctx.restore();
  }
  ctx.restore();
}

function noodleStrand(x1, y1, x2, y2, w, wave, phase, t, tone) {
  ctx.beginPath();
  const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
  const sway = reduced.matches ? 0 : Math.sin(t * 1.1 + phase) * wave * .35;
