  ctx.bezierCurveTo(x1 + wave + sway, y1 + (y2 - y1) * .33, x2 - wave - sway, y1 + (y2 - y1) * .66, x2, y2);
  ctx.strokeStyle = tone; ctx.lineWidth = Math.max(1, w * S); ctx.lineCap = "round"; ctx.stroke();
